-- CAMPUSLINK MySQL schema. The same schema is represented in models.py and is
-- automatically created by `python seed.py` for a new local database.
CREATE DATABASE IF NOT EXISTS campuslink CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE campuslink;

CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(24) NOT NULL, phone VARCHAR(40), date_of_birth DATE, active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_users_role(role));
CREATE TABLE branches (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE students (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, college_name VARCHAR(180) NOT NULL DEFAULT '', student_number VARCHAR(40) UNIQUE, branch_id INT, year INT DEFAULT 4, semester INT DEFAULT 8, graduation_year INT, gender VARCHAR(40) NOT NULL DEFAULT '', courses TEXT NOT NULL, achievements TEXT NOT NULL, interest_tags TEXT NOT NULL, interests TEXT NOT NULL, cgpa FLOAT DEFAULT 0, attendance FLOAT DEFAULT 0, career_goal VARCHAR(180), bio TEXT, resume_filename VARCHAR(255), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(branch_id) REFERENCES branches(id));
CREATE TABLE companies (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, company_name VARCHAR(160) NOT NULL, description TEXT, industry VARCHAR(100), website VARCHAR(255), location VARCHAR(120), recruiter_name VARCHAR(120), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE placement_officers (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, department VARCHAR(120), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE skills (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, category VARCHAR(80), INDEX ix_skills_name(name));
CREATE TABLE student_skills (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, skill_id INT NOT NULL, proficiency INT DEFAULT 60, UNIQUE KEY uq_student_skill(student_id,skill_id), INDEX ix_student_skills_student_id(student_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE);
CREATE TABLE jobs (id INT AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, title VARCHAR(160) NOT NULL, description TEXT, minimum_cgpa FLOAT DEFAULT 0, minimum_attendance FLOAT DEFAULT 0, eligible_branches TEXT, experience VARCHAR(100), certifications TEXT, salary VARCHAR(80), location VARCHAR(120), vacancies INT DEFAULT 1, deadline DATE, terms TEXT, active BOOLEAN DEFAULT TRUE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX ix_jobs_company_id(company_id), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE job_skills (id INT AUTO_INCREMENT PRIMARY KEY, job_id INT NOT NULL, skill_id INT NOT NULL, required BOOLEAN DEFAULT TRUE, UNIQUE KEY uq_job_skill(job_id,skill_id), INDEX ix_job_skills_job_id(job_id), FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE, FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE);
CREATE TABLE applications (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, job_id INT NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'Applied', match_score FLOAT DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_application(student_id,job_id), INDEX ix_applications_student_id(student_id), INDEX ix_applications_job_id(job_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE);
CREATE TABLE projects (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, title VARCHAR(160) NOT NULL, description TEXT, technologies TEXT, github_url VARCHAR(500), demo_url VARCHAR(500), status VARCHAR(24) DEFAULT 'Pending', INDEX ix_projects_student_id(student_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE internships (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, company VARCHAR(160) NOT NULL, role VARCHAR(160), duration VARCHAR(80), description TEXT, certificate_url VARCHAR(500), status VARCHAR(24) DEFAULT 'Pending', INDEX ix_internships_student_id(student_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE certificates (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, name VARCHAR(180) NOT NULL, certificate_type VARCHAR(60), certificate_id VARCHAR(120), issuer VARCHAR(160), completion_date DATE, url VARCHAR(500), status VARCHAR(32) DEFAULT 'REQUIRES_REVIEW', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX ix_certificates_student_id(student_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE nptel_certificates (id INT AUTO_INCREMENT PRIMARY KEY, certificate_id INT NOT NULL UNIQUE, course_name VARCHAR(180) NOT NULL, score FLOAT, FOREIGN KEY(certificate_id) REFERENCES certificates(id) ON DELETE CASCADE);
CREATE TABLE quizzes (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, category VARCHAR(100) NOT NULL, duration_minutes INT DEFAULT 10, active BOOLEAN DEFAULT TRUE, INDEX ix_quizzes_category(category));
CREATE TABLE quiz_questions (id INT AUTO_INCREMENT PRIMARY KEY, quiz_id INT NOT NULL, prompt TEXT NOT NULL, options TEXT NOT NULL, answer_index INT NOT NULL, explanation TEXT, difficulty VARCHAR(16) NOT NULL DEFAULT 'Medium', topic VARCHAR(120) DEFAULT '', question_type VARCHAR(24) NOT NULL DEFAULT 'MCQ', answer_indices TEXT, INDEX ix_quiz_questions_quiz_id(quiz_id), FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE quiz_results (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, quiz_id INT NOT NULL, score FLOAT NOT NULL, correct_count INT DEFAULT 0, weak_areas TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX ix_quiz_results_student_id(student_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE quick_quiz_attempts (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, student_id INT NOT NULL, branch_id INT, attempt_date DATE NOT NULL, attempt_id VARCHAR(64) NOT NULL UNIQUE, status VARCHAR(16) NOT NULL, category VARCHAR(100) NOT NULL, topic VARCHAR(120) NOT NULL DEFAULT '', difficulty VARCHAR(16) NOT NULL, requested_difficulty VARCHAR(16) NOT NULL, question_count INT NOT NULL, quiz_id INT, question_ids TEXT NOT NULL, answers TEXT NOT NULL, answers_revision INT NOT NULL DEFAULT 0, score FLOAT, correct_count INT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME, UNIQUE KEY uq_quick_quiz_user_date(user_id,attempt_date), INDEX ix_quick_quiz_attempts_user_id(user_id), INDEX ix_quick_quiz_attempts_student_id(student_id), INDEX ix_quick_quiz_attempts_attempt_date(attempt_date), INDEX ix_quick_quiz_attempts_status(status), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE SET NULL);
CREATE TABLE interviews (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, category VARCHAR(80), status VARCHAR(24) DEFAULT 'In Progress', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX ix_interviews_student_id(student_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE interview_questions (id INT AUTO_INCREMENT PRIMARY KEY, category VARCHAR(80) NOT NULL, prompt TEXT NOT NULL, expected_keywords TEXT, INDEX ix_interview_questions_category(category));
CREATE TABLE interview_results (id INT AUTO_INCREMENT PRIMARY KEY, interview_id INT NOT NULL, question_id INT, answer TEXT, relevance_score FLOAT DEFAULT 0, communication_score FLOAT DEFAULT 0, feedback TEXT, INDEX ix_interview_results_interview_id(interview_id), FOREIGN KEY(interview_id) REFERENCES interviews(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES interview_questions(id));
CREATE TABLE notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(160) NOT NULL, message TEXT NOT NULL, link VARCHAR(255), `read` BOOLEAN DEFAULT FALSE, dedupe_key VARCHAR(180) UNIQUE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX ix_notifications_user_id(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE courses (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, skill VARCHAR(100) NOT NULL, level VARCHAR(40), url VARCHAR(500), duration VARCHAR(60), INDEX ix_courses_skill(skill));
CREATE TABLE student_progress (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, item_type VARCHAR(40) NOT NULL, item_name VARCHAR(180) NOT NULL, progress INT DEFAULT 0, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX ix_student_progress_student_id(student_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE placements (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, company_id INT, job_id INT, package_lpa FLOAT DEFAULT 0, placement_date DATE, INDEX ix_placements_student_id(student_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE SET NULL, FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE SET NULL);
CREATE TABLE calendar_events (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(180) NOT NULL, event_type VARCHAR(50), starts_at DATETIME NOT NULL, notes TEXT, INDEX ix_calendar_events_user_id(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE feedback (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT, rating INT NOT NULL, category VARCHAR(60) NOT NULL, message TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE resume_analyses (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, filename VARCHAR(255) NOT NULL, score FLOAT DEFAULT 0, result_json TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX ix_resume_analyses_student_id(student_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
-- Legacy table/column names are retained; email_hash stores only a reset-grant hash.
CREATE TABLE password_reset_challenges (id INT AUTO_INCREMENT PRIMARY KEY, email_hash CHAR(64) NOT NULL UNIQUE, user_id INT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at DATETIME, verified_at DATETIME, INDEX ix_password_reset_challenges_user_id(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE password_recovery_attempts (id INT AUTO_INCREMENT PRIMARY KEY, client_hash CHAR(64) NOT NULL UNIQUE, window_started_at DATETIME NOT NULL, attempts INT NOT NULL DEFAULT 0, blocked_until DATETIME, INDEX ix_password_recovery_attempts_client_hash(client_hash));
CREATE TABLE company_password_reset_otps (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, otp_hash CHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at DATETIME NOT NULL, attempts INT NOT NULL DEFAULT 0, INDEX ix_company_password_reset_otps_user_id(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
